package main

import "net/http"

func (s *Service) authorizePage(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("Referrer-Policy", "no-referrer")
	w.Header().Set("Content-Security-Policy", "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'self'; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'")
	w.Write([]byte(`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>连接电脑 · Random创造集市</title><style>[hidden]{display:none!important}body{font:16px/1.7 system-ui,sans-serif;background:#f7f9fc;color:#172333;margin:0}main{max-width:620px;margin:8vh auto;padding:28px;background:white;border:1px solid #d8e0eb;border-radius:18px}header{display:flex;gap:18px;align-items:center}img{width:52px;height:52px;object-fit:contain}h1{font-size:23px;margin:0}p{color:#516174}label{display:block;margin:18px 0}input{font:inherit;width:100%;box-sizing:border-box;padding:10px;border:1px solid #aeb9c8;border-radius:8px}button,a.button{font:inherit;padding:10px 16px;border-radius:8px;border:1px solid #244db0;background:#244db0;color:white;cursor:pointer;display:inline-block;text-decoration:none}button:disabled{opacity:.5;cursor:default}a{color:#244db0}article{border:1px solid #d8e0eb;border-radius:10px;padding:14px;margin:12px 0}#message{white-space:pre-wrap}@media(prefers-color-scheme:dark){body{background:#101620;color:#e8edf4}main{background:#182130;border-color:#34445a}p{color:#b0bfd2}article{border-color:#34445a}input{background:#101620;color:#e8edf4}}@media(max-width:650px){main{margin:16px;padding:20px}}</style><main><header><img src="/brand/rd-mark-square.png" alt=""><div><h1>Random创造集市</h1><div>授权 Tervell 连接这台电脑</div></div></header><p>只确认由你自己刚刚发起的连接。核对电脑名称和软件中的确认码；授权后自动续签，无需反复登录。</p><div id="login"><a class="button" href="/sign-in" target="_blank" rel="noopener">登录集市</a> <a href="/sign-up" target="_blank" rel="noopener">注册账号</a><p>先在本站登录，再回到此页点击检查。</p></div><button id="check">检查登录状态</button><p id="message" role="status" aria-live="polite"></p><label>电脑确认码<input id="code" maxlength="12" autocomplete="off"></label><button id="inspect" disabled>核对电脑</button><article id="details" hidden></article><button id="approve" hidden>确认是我的电脑，允许连接</button><h2>我的电脑</h2><div id="devices"></div></main><script>
let token='',inspectedCode='';const $=id=>document.getElementById(id),message=text=>$('message').textContent=text;const code=new URL(location.href).searchParams.get('code')||'';$('code').value=/^[A-F0-9]{12}$/.test(code)?code:'';
async function call(path,body){const response=await fetch('/connect/'+path,{method:'POST',headers:{'content-type':'application/json','authorization':'Bearer '+token},body:JSON.stringify(body||{}),credentials:'same-origin',signal:AbortSignal.timeout(15000)});const value=await response.json();if(!response.ok)throw Error(value.error||'操作失败');return value;}
async function devices(){const result=await call('account/devices');$('devices').replaceChildren();for(const d of result.devices){const row=document.createElement('article'),text=document.createElement('span');text.textContent=d.name+' · '+d.platform+' · '+(d.revoked?'已撤销':d.online?'在线':'离线');row.append(text);if(!d.revoked){const b=document.createElement('button');b.textContent='撤销';b.style.marginLeft='12px';b.onclick=async()=>{b.disabled=true;try{await call('account/revoke',{hostId:d.id});await devices();message('电脑连接权限已撤销。')}catch(e){message(e.message);b.disabled=false}};row.append(b)}$('devices').append(row)}}
$('check').onclick=async()=>{const button=$('check');button.disabled=true;try{const response=await fetch('/api/user/auth/refresh',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'}});const value=await response.json();if(!response.ok||!value.success||!value.data?.access_token)throw Error('请先在本站登录，再回到此页。');token=value.data.access_token;$('login').hidden=true;$('inspect').disabled=false;message('已登录。请核对需要连接的电脑。');await devices()}catch(e){message(e.message)}finally{button.disabled=false}};
$('code').addEventListener('input',()=>{inspectedCode='';$('approve').hidden=true;$('details').hidden=true});
$('inspect').onclick=async()=>{try{const d=await call('account/approve',{code:$('code').value,confirm:false});inspectedCode=$('code').value.trim().toUpperCase();$('details').textContent=d.name+' · '+d.platform+'\n身份指纹：'+d.fingerprint;$('details').hidden=false;$('approve').hidden=d.approved;message(d.approved?'电脑已经授权。请返回 Tervell 生成手机配对码；手机连接需要独立配对。':'确认码和电脑名称一致后，点击下方授权。')}catch(e){message(e.message)}};
$('approve').onclick=async()=>{const button=$('approve');button.disabled=true;try{await call('account/approve',{code:inspectedCode,confirm:true});message('电脑已授权。请返回电脑上的 Tervell，等待显示“电脑已连接”，再生成手机配对码交给手机。网页确认码不能用于手机配对。');button.hidden=true;await devices()}catch(e){message(e.message)}finally{button.disabled=false}};
</script></html>`))
}
